service.method:

SELECT MANAGE_NUMBER 
  FROM SSEAL
 WHERE HOUSE_CODE = ${HOUSE_CODE}
   AND COMPANY_CODE = ${COMPANY_CODE}
   AND SEAL_MG_USER_ID IN ($IN{IDS})
   AND DEL_FLAG = 'N'


UPDATE
	SUSMT 
SET
	PASS_CHECK_CNT = #{PASS_CHECK_CNT}
	, PW_RESET_FLAG =${PW_RESET_FLAG}
WHERE
	HOUSE_CODE = ${HOUSE_CODE}
AND USER_ID    = UPPER(${USER_ID})
